csui.define('csui/controls/selected.count/selected.count.control.view',['csui/lib/underscore', 'csui/lib/marionette3',
  'csui/behaviors/keyboard.navigation/tabable.region.behavior',
  'hbs!csui/controls/selected.count/impl/selected.count.control',
  'smart/controls/bulk.selection/bulk.selection.view',
  'csui/controls/node-type.icon/node-type.icon.view',
  'css!csui/controls/selected.count/impl/selected.count'
], function (_, Marionette, TabableRegionBehavior, template, BulkSelectionView, NodeTypeIconView) {
  'use strict';

  let SelectedCounterView = Marionette.View.extend({
    template: template,
    className: 'csui-selected-count',

    regions: {
      selectedCounter:{ 
        el:'.csui-selected-counter-region',
        replaceElement: true
      }
    },

    constructor: function SelectedCounterView(options) {
      options || (options = {});
      Marionette.View.prototype.constructor.apply(this, arguments);
    },

    behaviors: {
      TabableRegion: {
        behaviorClass: TabableRegionBehavior
      }
    },
    //Adaption to bulk selection smart control component
    onRender: function () {
      this.selectedCountView = new BulkSelectionView({
        collection: this.collection,
        getNodeTypeIconView: this.getNodeTypeIconView.bind(this)
      });
      this.showChildView('selectedCounter', this.selectedCountView);
    },

    getNodeTypeIconView: function(iconViewOptions) {
      return new NodeTypeIconView(iconViewOptions)
    },

    currentlyFocusedElement: function () {
      return this.selectedCountView?.selectedLabel?.el;
    }

  });

  return SelectedCounterView;
});
