csui.define('csui/controls/app.header/app.header.controls/logo/logo.view',[
  "nuc/lib/underscore",
  "nuc/lib/marionette3",
  "csui/utils/contexts/factories/branding.config.factory",
  "csui/utils/url",
  "csui/utils/node.links/node.links",
  "csui/utils/contexts/factories/application.scope.factory",
  "smart/themes/theming",
  'csui/utils/commonconfig.util',
  "i18n!csui/pages/start/nls/lang",
], function (
  _,
  Marionette,
  BrandingConfigFactory,
  Url,
  NodeLinks,
  ApplicationScopeModelFactory,
  theming,
  CommonConfigUtil,
  lang
) {
  "use strict";

  const isJato = () => theming.isJATOTheme();

  const getDefaultLogo = () => {
    return isJato() ?
      `data:image/svg+xml,%3Csvg%20width%3D%2226%22%20height%3D%2232%22%20viewBox%3D%220%200%2026%2032%22%20fill%3D%22none%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%0A%3Cpath%20d%3D%22M16.7189%204.00535H20.801C21.0366%204.00535%2021.2283%204.19243%2021.2283%204.42227V7.04139C21.2283%207.27124%2021.4201%207.45831%2021.6557%207.45831H25.5707C25.9104%207.45831%2026.1159%207.82446%2025.9296%208.10241L24.2228%2010.6708C24.1434%2010.791%2024.0091%2010.8605%2023.8639%2010.8605H21.6201C21.3845%2010.8605%2021.1927%2011.0476%2021.1927%2011.2774V18.1593C21.1599%2019.1669%2021.1599%2020.0168%2022.4831%2020.0168L23.8146%2019.9687C24.0584%2019.9606%2024.2584%2020.1504%2024.2584%2020.3856V23.3708C24.2584%2023.5766%2024.1023%2023.753%2023.8913%2023.7851C23.0338%2023.9107%2022.4393%2023.9829%2021.6448%2023.9829C19.9352%2023.9829%2018.0613%2023.8893%2016.9983%2022.3766C16.3216%2021.4012%2016.2887%2020.2359%2016.2887%2018.6618V4.41692C16.2887%204.18708%2016.4805%204%2016.7161%204L16.7189%204.00535Z%22%20fill%3D%22%231A6AFF%22%2F%3E%0A%3Cpath%20d%3D%22M9.19011%207.1829C3.98201%206.86219%20-0.31105%2011.0501%200.0177095%2016.1307C0.288936%2020.3213%203.77379%2023.7181%208.06959%2023.9827C13.2777%2024.3034%2017.5707%2020.1155%2017.242%2015.0349C16.9708%2010.8443%2013.4859%207.44749%209.19285%207.18023L9.19011%207.1829ZM9.13258%2019.3324C6.59839%2019.6451%204.46693%2017.5659%204.78473%2015.0911C5.00116%2013.4073%206.39839%2012.0443%208.12438%2011.8332C10.6586%2011.5205%2012.79%2013.6024%2012.4722%2016.0746C12.2558%2017.7583%2010.8586%2019.1186%209.13258%2019.3324Z%22%20fill%3D%22%231A6AFF%22%2F%3E%0A%3C%2Fsvg%3E%0A`
      :
      `data:image/svg+xml;base64,`
  };

  let LogoView = Marionette.View.extend({
    tagName: "otc-brand",

    attributes: function () { },

    template: false,

    constructor: function LogoView(options = {}) {
      Marionette.View.apply(this, arguments);

      this.brandingConfigData = this.options.context.getModel(
        BrandingConfigFactory
      );

      var connector = this.options?.context?._user?.connector;
      this.logoUrl = "/";

      if (connector) {
        let serverUrl = new Url(connector?.connection?.url ?? location.href);
        this.logoUrl = NodeLinks.getHomeUrl(serverUrl);
      }

      this.otcData = {
        logosrc: getDefaultLogo(),
        logourl: this.logoUrl,
        tooltipbrand: "",
        primarytext: "",
        secondarytext: "",
        versiontext: "",
      };
      this.updateData();

      this.listenTo(
        this.brandingConfigData,
        "change:branding",
        this.updateData
      );
      
      this.listenTo( this.options.context.brandingConfigData, 'change:brand', this.updateData);
      this.listenTo(this.options.context, "sync:perspective", this.updateData);

      // let's execute the defaul action which is taking care in the parent view (ie., LogoView)
      this.performClickAction = false;
    },

    onShow: function () {
      this.options?.otcEl?.addEventListener(
        "click",
        _.bind(this._onClick, this)
      );
    },

    _onClick: function (event) {
      // clicking on logo reset application scope to default.
      this.applicationScope.set("id", "");
    },

    updateData: function () {
      let fromCtx = this.options?.context?.previewBranding?.get(
        "brandingSettingCodes"
      );
      let fromData = this?.options?.context?.brandingConfigData?.get(
        "brandingSettingCodes"
      );
      let backgroundColor = fromCtx?.customBrandingBgColor ?? fromData?.customBrandingBgColor ?? "";
      let primaryText = fromCtx?.primaryText ?? fromData?.primaryText ?? "";
      let secondaryText =
        fromCtx?.secondaryText ?? fromData?.secondaryText ?? "";
      let versionText = fromCtx?.versionText ?? fromData?.versionText ?? "";
      let logoSrc, theme;
      if(this?.options?.parentView?._parent?.options?.el?.tagName?.toLowerCase() === 'body'){
        theme = theming.getTheme();// this is for page load scenario
      }else{
        theme = this?.options?.parentView?._parent?.options?.el?.attr('branding-theme');
      }
      let brandSettingsPreviewThemes = this?.options?.context?.previewBranding?.get("brandingSettingCodes")?.themes,
      brandingConfigDataThemes = this?.options?.context?.brandingConfigData?.get("brandingSettingCodes")?.themes;
      if(isJato() && theme && CommonConfigUtil.enableJatoBranding()){

        logoSrc = brandSettingsPreviewThemes? brandSettingsPreviewThemes[theme]?.brandLogoUri:brandSettingsPreviewThemes ?? brandingConfigDataThemes? brandingConfigDataThemes[theme]?.brandLogoUri:brandingConfigDataThemes;
      }else{
        logoSrc =
        this?.options?.context?.previewBranding?.get("brandLogoUri") ??
        this?.options?.context?.brandingConfigData?.get("brandLogoUri");
      }

      logoSrc = logoSrc?.length ? logoSrc : getDefaultLogo();

      this.applicationScope =
        this.options?.applicationScope ??
        this.options.context.getModel(ApplicationScopeModelFactory);
      let logoUrl = !!this?.applicationScope?.id?.length ? this.logoUrl : "";
      let tooltipbrand = !!this?.applicationScope?.id?.length
        ? lang.LandingPageBackTo
        : "";

      this.otcData = {
        logosrc: logoSrc,
        logourl: logoUrl,
        tooltipbrand: tooltipbrand,
        primarytext: primaryText,
        secondarytext: secondaryText,
        versiontext: versionText,
        backgroundColor,
      };
      this.trigger("data:synced");
    },
  });

  return LogoView;
});
